// spell-checker:ignore (ToDO) allocs bset dflag cflag sflag tflag

mod operation;
mod unicode_table;

use clap::{crate_version, value_parser, Arg, ArgAction, Command};
use operation::{
    Sequence, SqueezeOperation, SymbolTranslator, TranslateOperation,
};
use std::ffi::OsString;
use std::io::{stdin, stdout, BufRead, BufWriter, Write};
use uucore::{format_usage, help_about, help_section, help_usage, os_str_as_bytes, show};

use crate::operation::DeleteOperation;
use uucore::display::Quotable;
use uucore::error::{UResult, USimpleError, UUsageError};

const ABOUT: &str = help_about!("tr.md");
const AFTER_HELP: &str = help_section!("after help", "tr.md");
const USAGE: &str = help_usage!("tr.md");

mod options {
    pub const COMPLEMENT: &str = "complement";
    pub const DELETE: &str = "delete";
    pub const SQUEEZE: &str = "squeeze-repeats";
    pub const TRUNCATE_SET1: &str = "truncate-set1";
    pub const SETS: &str = "sets";
}

#[uucore::main]
pub fn uumain(args: impl uucore::Args) -> UResult<()> {
    let matches = uu_app().after_help(AFTER_HELP).try_get_matches_from(args)?;

    let delete_flag = matches.get_flag(options::DELETE);
    let complement_flag = matches.get_flag(options::COMPLEMENT);
    let squeeze_flag = matches.get_flag(options::SQUEEZE);
    let truncate_set1_flag = matches.get_flag(options::TRUNCATE_SET1);

    // Ultimately this should be OsString, but we might want to wait for the
    // pattern API on OsStr
    let sets: Vec<_> = matches
        .get_many::<OsString>(options::SETS)
        .into_iter()
        .flatten()
        .map(ToOwned::to_owned)
        .collect();

    let sets_len = sets.len();
    check_operand_count(delete_flag, squeeze_flag, &sets)?;

    if let Some(first) = sets.first() {
        let slice = os_str_as_bytes(first)?;

        let mut iter = slice.iter();

        if let Some(b'\\') = iter.next_back() {
            match iter.next_back() {
                Some(b'\\') => {
                    // The trailing backslash has a backslash preceding it, so it is properly escaped
                }
                _ => {
                    // The trailing backslash has a non-backslash character before it OR is the only character in the
                    // string, so the warning applies
                    show!(USimpleError::new(
                        0,
                        "warning: an unescaped backslash at end of string is not portable"
                    ));
                }
            }
        }
    }

    let stdin = stdin();
    let mut locked_stdin = stdin.lock();
    let stdout = stdout();
    let locked_stdout = stdout.lock();
    let mut buffered_stdout = BufWriter::new(locked_stdout);

    // According to the man page: translating only happens if deleting or if a second set is given
    let translating = !delete_flag && sets.len() > 1;
    let mut sets_iter = sets.iter().map(|c| c.as_os_str());
    let set1_os = sets_iter.next().unwrap_or_default();
    let set2_os = sets_iter.next().unwrap_or_default();

    #[cfg(unix)]
    let set1_bytes: &[u8] = {
        use std::os::unix::ffi::OsStrExt;
        set1_os.as_bytes()
    };
    #[cfg(not(unix))]
    let set1_bytes: &[u8] = match set1_os.to_str() {
        Some(text) => text.as_bytes(),
        None => {
            return Err(UUsageError::new(
                1,
                "invalid UTF-8 was detected in one or more arguments",
            ));
        }
    };

    #[cfg(unix)]
    let set2_bytes: &[u8] = {
        use std::os::unix::ffi::OsStrExt;
        set2_os.as_bytes()
    };
    #[cfg(not(unix))]
    let set2_bytes: &[u8] = match set2_os.to_str() {
        Some(text) => text.as_bytes(),
        None => {
            return Err(UUsageError::new(
                1,
                "invalid UTF-8 was detected in one or more arguments",
            ));
        }
    };

    let (set1, set2) = Sequence::solve_set_characters(
        set1_bytes,
        set2_bytes,
        complement_flag,
        // if we are not translating then we don't truncate set1
        truncate_set1_flag && translating,
        translating,
    )?;

    // '*_op' are the operations that need to be applied, in order.
    let mut translator: Box<dyn SymbolTranslator> = if delete_flag {
        if squeeze_flag {
            let delete_op = DeleteOperation::new(set1);
            let squeeze_op = SqueezeOperation::new(set2);
            Box::new(delete_op.chain(squeeze_op))
        } else {
            Box::new(DeleteOperation::new(set1))
        }
    } else if squeeze_flag {
        if sets_len < 2 {
            Box::new(SqueezeOperation::new(set1))
        } else {
            let translate_op = TranslateOperation::new(set1, set2.clone())?;
            let squeeze_op = SqueezeOperation::new(set2);
            Box::new(translate_op.chain(squeeze_op))
        }
    } else {
        Box::new(TranslateOperation::new(set1, set2)?)
    };

    let mut input_buf = Vec::new();
    let mut output_buf = Vec::new();
    while locked_stdin
        .read_until(b'\n', &mut input_buf)
        .map_or(false, |length| length > 0)
    {
        let filtered = input_buf
            .iter()
            .filter_map(|current| translator.translate(*current));
        output_buf.extend(filtered);
        buffered_stdout.write_all(&output_buf).unwrap();
        input_buf.clear();
        output_buf.clear();
    }
    Ok(())
}

fn check_operand_count(
    delete_flag: bool,
    squeeze_flag: bool,
    sets: &[OsString],
) -> UResult<()> {
    let sets_len = sets.len();

    if sets.is_empty() {
        return Err(UUsageError::new(1, "missing operand"));
    }

    if !(delete_flag || squeeze_flag) && sets_len < 2 {
        return Err(UUsageError::new(
            1,
            format!(
                "missing operand after {}\nTwo strings must be given when translating.",
                sets[0].quote()
            ),
        ));
    }

    if delete_flag & squeeze_flag && sets_len < 2 {
        return Err(UUsageError::new(
            1,
            format!(
                "missing operand after {}\nTwo strings must be given when deleting and squeezing.",
                sets[0].quote()
            ),
        ));
    }

    if sets_len > 1 {
        let start = "extra operand";
        if delete_flag && !squeeze_flag {
            let op = sets[1].quote();
            let msg = if sets_len == 2 {
                format!(
                    "{} {}\nOnly one string may be given when deleting without squeezing repeats.",
                    start, op,
                )
            } else {
                format!("{} {}", start, op,)
            };
            return Err(UUsageError::new(1, msg));
        }
        if sets_len > 2 {
            let op = sets[2].quote();
            let msg = format!("{} {}", start, op);
            return Err(UUsageError::new(1, msg));
        }
    }

    Ok(())
}

